<?php
declare(strict_types=1);
require __DIR__ . '/api/bootstrap.php';
$user=current_user();if(!$user){header('Location: login.php');exit;}if(($user['role']??'')==='admin'){header('Location: admin.php');exit;}
refresh_expired_licenses();$license=latest_license((int)$user['id']);$hasAccess=user_has_access($user);$paymentOn=payment_enabled()&&app_setting('license_purchase_enabled','0')==='1';$plans=db()->query('SELECT * FROM plans WHERE active=1 AND price_cents>0 ORDER BY duration_days')->fetchAll();
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#070b10"><title>Acesso e PIX · MusicRoad</title><style>:root{color-scheme:dark;--bg:#071018;--panel:#0e1b27;--line:#203547;--text:#f7f9fb;--muted:#91a5b5;--orange:#ff7a1a;--green:#32d583}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 70% 0,#19364d 0,transparent 35%),var(--bg);color:var(--text);font-family:Inter,system-ui,sans-serif}.wrap{max-width:960px;margin:auto;padding:38px 18px}.brand{font-weight:900;font-size:19px}.hero{margin:30px 0 18px;padding:25px;border:1px solid var(--line);background:linear-gradient(160deg,#122637,#0b1721);border-radius:22px}h1{font-size:35px;letter-spacing:-.04em;margin:0 0 10px}.muted,p{color:var(--muted);line-height:1.5}.status{display:inline-flex;padding:7px 10px;border-radius:999px;background:#2b1912;color:#ffc79e;font-size:11px;font-weight:900}.status.ok{background:#0e2d20;color:#91ecc0}.plans{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.plan{border:1px solid var(--line);border-radius:18px;background:var(--panel);padding:18px}.plan strong{font-size:21px}.price{font-size:25px;font-weight:900;margin:12px 0}.plan button,.button{width:100%;border:0;border-radius:12px;padding:12px;background:var(--orange);color:#17100a;font-weight:900;cursor:pointer;text-decoration:none;display:flex;justify-content:center}.box{border:1px solid var(--line);border-radius:16px;padding:16px;margin-top:14px;background:#0a1721}.top{display:flex;justify-content:space-between;gap:12px;align-items:center}.top a{color:#b6c6d3;text-decoration:none}.pix-modal{position:fixed;inset:0;background:rgba(0,0,0,.72);display:none;align-items:center;justify-content:center;padding:18px;z-index:99}.pix-modal.open{display:flex}.pix-card{width:min(100%,520px);max-height:92vh;overflow:auto;background:#0b1823;border:1px solid #29455b;border-radius:22px;padding:22px}.pix-head{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.close{border:0;background:#172938;color:#d8e4ec;border-radius:10px;padding:9px 11px}.cpfbox{display:grid;gap:7px;margin:16px 0}.cpfbox input{border:1px solid var(--line);background:#07131d;color:#fff;border-radius:12px;padding:14px;font:inherit}.qr{width:240px;height:240px;display:block;margin:14px auto;background:#fff;border-radius:12px;padding:8px}.code{width:100%;min-height:86px;border:1px solid var(--line);background:#07131d;color:#d8e7f0;border-radius:10px;padding:10px;word-break:break-all;font-size:11px}.pix-actions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.pix-actions button{border:0;border-radius:11px;padding:12px;font-weight:900}.copy{background:var(--orange)}.check{background:#173548;color:#eef7fc}.pix-status{margin-top:12px;padding:11px;border-radius:10px;background:#122638;color:#bad0df;font-size:12px}.secure{font-size:11px;color:#7190a5;margin-top:10px}@media(max-width:700px){.plans{grid-template-columns:1fr}h1{font-size:30px}.pix-actions{grid-template-columns:1fr}}</style></head><body><main class="wrap"><div class="top"><div class="brand">MusicRoad</div><a href="logout.php">Sair</a></div><section class="hero"><span class="status <?=$hasAccess?'ok':''?>"><?=$hasAccess?'ACESSO ATIVO':'ACESSO ENCERRADO'?></span><h1><?=$hasAccess?'Seu MusicRoad está liberado.':'Escolha um plano e pague por PIX.'?></h1><p>Usuário: <?=htmlspecialchars((string)$user['name'])?><?php if($license): ?> · validade até <strong><?=htmlspecialchars(date('d/m/Y H:i',strtotime((string)$license['ends_at'])))?></strong><?php endif; ?></p><?php if($hasAccess): ?><a class="button" href="index.php">ABRIR MUSICROAD</a><?php endif; ?></section>
<?php if(!$paymentOn): ?><section class="box"><strong>PIX temporariamente indisponível</strong><p>O administrador ainda não ativou o módulo Mercado Pago PIX.</p></section><?php elseif(!$plans): ?><section class="box"><strong>Planos ainda sem preço</strong><p>O administrador precisa configurar pelo menos um plano com preço maior que zero.</p></section><?php else: ?><h2>Planos</h2><div class="plans"><?php foreach($plans as $p): ?><article class="plan"><strong><?=htmlspecialchars($p['name'])?></strong><p><?=$p['duration_days']?> dias de acesso</p><div class="price">R$ <?=number_format($p['price_cents']/100,2,',','.')?></div><button data-plan="<?=$p['id']?>" data-name="<?=htmlspecialchars($p['name'],ENT_QUOTES)?>" data-price="<?=number_format($p['price_cents']/100,2,',','.')?>">PAGAR COM PIX</button></article><?php endforeach; ?></div><?php endif; ?></main>
<div class="pix-modal" id="pixModal"><section class="pix-card"><div class="pix-head"><div><span class="status ok">MERCADO PAGO PIX</span><h2 id="pixTitle">Gerar PIX</h2><p id="pixPrice"></p></div><button class="close" id="closePix">✕</button></div><div id="pixForm"><label class="cpfbox">CPF do pagador<input id="pixCpf" inputmode="numeric" maxlength="14" placeholder="000.000.000-00"></label><button class="button" id="generatePix">GERAR QR CODE PIX</button><div class="secure">O CPF é enviado diretamente ao Mercado Pago para gerar o pagamento e não é gravado no banco do MusicRoad.</div></div><div id="pixReady" hidden><img class="qr" id="pixQr" alt="QR Code PIX"><div class="code" id="pixCode"></div><div class="pix-actions"><button class="copy" id="copyPix">COPIAR PIX</button><button class="check" id="checkPix">JÁ PAGUEI · VERIFICAR</button></div><div class="pix-status" id="pixStatus">Aguardando pagamento…</div></div></section></div>
<script nonce="<?=htmlspecialchars(csp_nonce(),ENT_QUOTES)?>">window.MR_CSRF=<?=json_encode(csrf_token())?>;(function(){let planId=0,orderId=0,timer=0;const modal=document.getElementById('pixModal'),form=document.getElementById('pixForm'),ready=document.getElementById('pixReady'),status=document.getElementById('pixStatus');document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{planId=Number(b.dataset.plan);document.getElementById('pixTitle').textContent=b.dataset.name;document.getElementById('pixPrice').textContent='R$ '+b.dataset.price;form.hidden=false;ready.hidden=true;modal.classList.add('open')});document.getElementById('closePix').onclick=()=>{modal.classList.remove('open');if(timer)clearInterval(timer)};document.getElementById('generatePix').onclick=async function(){const cpf=document.getElementById('pixCpf').value;this.disabled=true;this.textContent='GERANDO…';try{const r=await fetch('api/payment_pix.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-Token':window.MR_CSRF},body:JSON.stringify({plan_id:planId,cpf})});const j=await r.json();if(!j.ok)throw new Error(j.error||'Falha ao gerar PIX');orderId=Number(j.order_id);document.getElementById('pixQr').src=j.qr_code_base64?'data:image/png;base64,'+j.qr_code_base64:'';document.getElementById('pixQr').style.display=j.qr_code_base64?'block':'none';document.getElementById('pixCode').textContent=j.qr_code||j.ticket_url||'';form.hidden=true;ready.hidden=false;status.textContent='PIX gerado. Aguardando confirmação do Mercado Pago…';startPoll()}catch(e){alert(e.message)}finally{this.disabled=false;this.textContent='GERAR QR CODE PIX'}};async function check(){if(!orderId)return;try{const r=await fetch('api/payment_status.php?order_id='+orderId,{credentials:'same-origin',headers:{'Accept':'application/json'}});const j=await r.json();if(j.approved||j.has_access){status.textContent='Pagamento aprovado ✓ Acesso liberado.';if(timer)clearInterval(timer);setTimeout(()=>location.href='index.php',900)}else status.textContent='Status: '+String(j.status||'pendente').replaceAll('_',' ')+' · aguardando confirmação…'}catch(e){}}function startPoll(){check();if(timer)clearInterval(timer);timer=setInterval(check,5000)}document.getElementById('checkPix').onclick=check;document.getElementById('copyPix').onclick=async()=>{const code=document.getElementById('pixCode').textContent||'';try{await navigator.clipboard.writeText(code);status.textContent='Código PIX copiado ✓'}catch(e){prompt('Copie o PIX:',code)}}})();</script></body></html>